parameters.jsCode:
const rows = $('Get Upcoming Bookings').all().map(i => i.json).filter(r => r && r.booking_time && r.booking_date && String(r.status || 'confirmed').toLowerCase() !== 'cancelled');
const chatId = String($('Telegram Trigger').first().json.message?.chat?.id ?? '');
const nowMs = Date.now();
const holds = $('Get Active Holds').all().map(i => i.json).filter(h => h && h.booking_date && h.booking_time && h.released !== true && Number(h.expires_ms) > nowMs);
const taken = {};
for (const r of rows) {
  const d = String(r.booking_date).slice(0, 10);
  (taken[d] = taken[d] || new Set()).add(String(r.booking_time).slice(0, 5));
}
// Slots held by OTHER customers who are paying right now count as taken (the customer's own hold stays free for them)
for (const h of holds) {
  if (String(h.chat_id) === chatId) continue;
  const d = String(h.booking_date).slice(0, 10);
  (taken[d] = taken[d] || new Set()).add(String(h.booking_time).slice(0, 5));
}
const cairo = new Date(new Date().toLocaleString('en-US', { timeZone: 'Africa/Cairo' }));
const pad = n => String(n).padStart(2, '0');
const nowMin = cairo.getHours() * 60 + cairo.getMinutes();
const days = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
const fmt = h => h === 12 ? '12:00 ظهرًا' : ((h % 12) + ':00 ' + (h < 12 ? 'ص' : 'م'));
const lines = ['Generated now at ' + pad(cairo.getHours()) + ':' + pad(cairo.getMinutes()) + ' Cairo time. This list is fresh and overrides anything said earlier in the conversation.'];
for (let k = 0; k < 14; k++) {
  const dt = new Date(cairo.getFullYear(), cairo.getMonth(), cairo.getDate() + k);
  const d = dt.getFullYear() + '-' + pad(dt.getMonth() + 1) + '-' + pad(dt.getDate());
  const label = days[dt.getDay()] + (k === 0 ? ' - النهاردة' : k === 1 ? ' - بكرة' : '');
  const set = taken[d] || new Set();
  const free = [];
  const booked = [];
  for (let h = 10; h < 18; h++) {
    const code = pad(h) + ':00';
    if (set.has(code)) { booked.push(fmt(h)); continue; }
    if (k === 0 && h * 60 <= nowMin) continue;
    free.push(fmt(h) + ' (code ' + code + ')');
  }
  lines.push(d + ' ' + label + '\n  FREE: ' + (free.length ? free.join(' | ') : 'NO FREE TIMES') + '\n  TAKEN: ' + (booked.length ? booked.join(' | ') : 'none'));
}
// Active upcoming bookings that belong to THIS Telegram account (the customer's own data only)
const mine = rows.filter(r => String(r.customer_chat_id || '') === chatId);
const myLines = mine.length
  ? mine.map(r => 'id ' + r.id + ' | name: ' + r.customer_name + ' | phone: ' + r.customer_phone + ' | ' + String(r.booking_date).slice(0, 10) + ' ' + String(r.booking_time).slice(0, 5) + ' | service_id ' + r.service_id + ' | status ' + r.status + ' | payment ' + r.payment_status + ' | deposit ' + r.deposit_amount).join('\n')
  : 'none';
const hhmm = ms => new Date(ms).toLocaleTimeString('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit' });
const holdLines = holds.filter(h => String(h.chat_id) === chatId).map(h => 'PAYMENT IN PROGRESS: ' + String(h.booking_date).slice(0, 10) + ' ' + String(h.booking_time).slice(0, 5) + ' is held for this customer until ' + hhmm(Number(h.expires_ms)) + ' Cairo time');

// ---- Deterministic pre-check of the phone in the latest message (the AI must never count digits itself)
const msg = String($('Telegram Trigger').first().json.message?.text ?? '');
const AR_D = '٠١٢٣٤٥٦٧٨٩', FA_D = '۰۱۲۳۴۵۶۷۸۹';
const txt = msg.replace(/[٠-٩]/g, c => AR_D.indexOf(c)).replace(/[۰-۹]/g, c => FA_D.indexOf(c));
const normPhone = p => {
  let d = String(p || '').replace(/\D/g, '');
  if (d.startsWith('0020')) d = '0' + d.slice(4);
  else if (d.length === 12 && d.startsWith('20')) d = '0' + d.slice(2);
  else if (d.length === 10 && /^1[0125]/.test(d)) d = '0' + d;
  return d;
};
const cands = txt.match(/\+?\d[\d\s\-().]{7,}\d/g) || [];
let phoneNote = 'No phone number in the latest message.';
let found = false;
let stripped = txt;
for (const c of cands) {
  if (c.replace(/\D/g, '').length < 9) continue;
  stripped = stripped.replace(c, ' ');
  const p = normPhone(c);
  if (/^01[0125]\d{8}$/.test(p)) {
    if (!found) { found = true; phoneNote = p + ' -> VALID' + (c.trim() !== p ? ' (normalized from ' + c.trim() + ')' : '') + '. Use exactly this number.'; }
  } else if (!found) {
    phoneNote = c.trim() + ' -> INVALID: ' + (p.length !== 11 ? 'it has ' + p.length + ' digits instead of 11' : 'the prefix must be 010, 011, 012 or 015') + '.';
  }
}
const nameCand = cands.length ? stripped.replace(/[^\u0600-\u06FFa-zA-Z\s]/g, ' ').replace(/\s+/g, ' ').trim() : '';
const nw = nameCand ? nameCand.split(' ').filter(Boolean).length : 0;
const nameNote = !cands.length ? 'n/a (no phone in this message, so no name was parsed)' : (nw ? '[' + nameCand + '] -> ' + nw + (nw >= 2 ? ' words (OK, at least two names)' : ' word (NOT ENOUGH: ask for the full name, at least two names)') : 'no name in this message (use one given earlier in the conversation, if any)');
const phone_check = [
  '- Phone in the latest message: ' + phoneNote,
  '- Name in the latest message: ' + nameNote,
  '- Spelling of names and matching against the account are NOT judged here: call verify_identity once you have a name and a valid phone.'
].join('\n');

return [{ json: { availability: lines.join('\n'), chat_id: chatId, my_bookings: myLines + (holdLines.length ? '\n' + holdLines.join('\n') : ''), phone_check: phone_check } }];

// 1) Find the Paymob link the tool generated in THIS turn (so the AI can never mangle it)
// 2) Strip any raw link from the AI text (the Pay button carries it)
// 3) Escape for Telegram HTML and respect the 4096-char limit
const j = $input.first().json;
const out = String(j.output ?? '').trim();
const steps = Array.isArray(j.intermediateSteps) ? j.intermediateSteps : [];
let payUrl = '';
for (const s of steps) {
  const tool = s && s.action && s.action.tool;
  if (tool !== 'generate_payment_link') continue;
  const obs = s.observation;
  let text = typeof obs === 'string' ? obs : JSON.stringify(obs || '');
  text = text.split('\\"').join('"');
  const k = text.indexOf('"payment_url"');
  if (k > -1) {
    const a = text.indexOf('"', text.indexOf(':', k) + 1);
    const b = text.indexOf('"', a + 1);
    if (a > -1 && b > a) payUrl = text.slice(a + 1, b);
  }
}
if (!payUrl) {
  const m = out.match(/https?:\/\/\S*unifiedcheckout\S*/);
  if (m) payUrl = m[0];
}
const stripped = out.replace(/https?:\/\/\S*unifiedcheckout\S*/g, '').replace(/\n{3,}/g, '\n\n').trim();
const safe = stripped.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fallback = 'عذراً، ممكن توضحلي طلبك أكتر؟ / Sorry, could you rephrase that?';
return [{ json: { reply: (safe || fallback).slice(0, 4000), pay_url: payUrl, has_pay: payUrl ? 'yes' : 'no' } }];
